                onChange={(e) => setAmount(e.target.value)}
                placeholder="0,00"
              />
            </label>
            {isReceivable ? null : (
              <label className="block space-y-1">
                <span className={labelClass}>Desconto (R$)</span>
                <Input
                  type="number"
                  step="0.01"
                  min="0"
                  value={discount}
                  onChange={(e) => setDiscount(e.target.value)}
                  placeholder="0,00"
