function reportPeriod(months: number): { from: string; to: string } {
  const to = new Date();
  const from = new Date();
  from.setMonth(from.getMonth() - months + 1);
  from.setDate(1);
  const pad = (d: Date) => d.toISOString().slice(0, 10);
  return { from: pad(from), to: pad(to) };
}

